def parse_block_spoiler(block: 'BlockParser', m: Match[str], state:
    'BlockState') ->int:
    pos = m.end()
    text = m.group(0)
    while pos < len(state.src):
        next_line_match = _BLOCK_SPOILER_START.match(state.src, pos)
        if not next_line_match:
            break
        line_end = state.src.find('\n', pos)
        if line_end == -1:
            line_end = len(state.src)
        text += state.src[pos:line_end + 1]
        pos = line_end + 1

    text = _BLOCK_SPOILER_START.sub('', text)
    state.append_token({'type': 'block_spoiler', 'raw': text})
    return pos


def render_block_spoiler(renderer: 'BaseRenderer', text: str) ->str:
    return '<div class="spoiler">\n' + text + '</div>\n'


def spoiler(md: 'Markdown') ->None:
    md.block.register('block_spoiler', _BLOCK_SPOILER_MATCH, parse_block_spoiler)
    md.inline.register('inline_spoiler', INLINE_SPOILER_PATTERN, parse_inline_spoiler)

    if md.renderer and hasattr(md.renderer, 'block_spoiler'):
        md.renderer.block_spoiler = lambda text: render_block_spoiler(md.renderer, text)
    if md.renderer and hasattr(md.renderer, 'inline_spoiler'):
        md.renderer.inline_spoiler = lambda text: render_inline_spoiler(md.renderer, text)
